const API = window.API_BASE_URL || (location.hostname === 'localhost' ? 'http://localhost:8000/api/v1' : 'https://ideal-marcenaria-api.onrender.com/api/v1');
const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const state = { user:null, resource:null, id:null, rows:[], categories:[], customers:[], suppliers:[], search:'', status:'', csrfToken:'', accessToken:'' };
const labels = {dashboard:'Dashboard',customers:'Clientes',quotes:'Orçamentos',projects:'Produção',suppliers:'Fornecedores',materials:'Insumos',products:'Produtos',categories:'Serviços',users:'Usuários',activities:'Histórico'};
const statusLabels = {pending:'Pendente',analysis:'Em análise',approved:'Aprovado',sent:'Enviado',accepted:'Aceito',declined:'Recusado pelo cliente',rejected:'Recusado',completed:'Concluído',planning:'Planejamento',in_progress:'Em andamento',measurement:'Medição',technical_design:'Projeto técnico',purchasing:'Compras',production:'Produção',installation:'Instalação',delivered:'Entregue',cancelled:'Cancelado'};
const csrf = () => state.csrfToken || document.cookie.split('; ').find(x=>x.startsWith('csrf_token='))?.split('=')[1] || '';
const escapeHtml = (v='') => String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const money = v => Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
let refreshPromise = null;
let sessionVersion = 0;
function toast(message,type='success'){const el=$('#toast');if(!el)return;el.textContent=message;el.className=`toast show ${type}`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className='toast',3500)}
async function refreshSession() {
  if (!refreshPromise) {
    refreshPromise = api('/auth/refresh', { method: 'POST' }, false)
      .finally(() => { refreshPromise = null; });
  }
  return refreshPromise;
}
async function api(path, options = {}, retryAuth = true) {
  const requestVersion = sessionVersion;
  const opts = { credentials: 'include', ...options, headers: { ...(options.headers || {}) } };
  if (state.accessToken && !opts.headers.Authorization) {
    opts.headers.Authorization = `Bearer ${state.accessToken}`;
  }
  if (opts.body && !(opts.body instanceof URLSearchParams) && typeof opts.body !== 'string') {
    opts.headers['Content-Type'] = 'application/json';
    opts.body = JSON.stringify(opts.body);
  }
  if (['POST', 'PUT', 'PATCH', 'DELETE'].includes(opts.method) && csrf()) {
    opts.headers['X-CSRF-Token'] = csrf();
  }
  const res = await fetch(API + path, opts);
  if (res.status === 204) {
    if (path === '/auth/logout') state.accessToken = '';
    return null;
  }
  const data = await res.json().catch(() => ({}));
  if (res.status === 401 && retryAuth && !path.startsWith('/auth/')) {
    // A delayed response may belong to the session another request already renewed.
    if (requestVersion === sessionVersion) await refreshSession();
    return api(path, options, false);
  }
  if (!res.ok) {
    throw new Error(data.detail || (res.status === 401 ? 'Sessão expirada. Faça login novamente.' : `Erro ${res.status}`));
  }
  if (typeof data?.csrf_token === 'string') state.csrfToken = data.csrf_token;
  if ((path === '/auth/login' || path === '/auth/refresh') && typeof data?.access_token === 'string') {
    state.accessToken = data.access_token;
  }
  if (path === '/auth/login' || path === '/auth/refresh') sessionVersion += 1;
  return data;
}
function openAuth(view='login'){const o=$('#auth-overlay');o.classList.remove('hidden');o.setAttribute('aria-hidden','false');showAuth(view)}
function closeAuth(){const o=$('#auth-overlay');o.classList.add('hidden');o.setAttribute('aria-hidden','true')}
function showAuth(view){['login','register','recovery','reset'].forEach(v=>$(`#${v}-view`)?.classList.toggle('hidden',v!==view))}
function showWhatsApp(message='Olá! Quero conhecer a plataforma Multi-Marcenarias para minha marcenaria.'){const number=window.WHATSAPP_NUMBER||'5513981236650';window.open(`https://wa.me/${String(number).replace(/\D/g,'')}?text=${encodeURIComponent(message)}`,'_blank','noopener')}
function setupPublic(){$$('#open-login').forEach(b=>b.addEventListener('click',()=>openAuth('login')));$('#close-auth').addEventListener('click',closeAuth);$('#auth-overlay').addEventListener('click',e=>{if(e.target.id==='auth-overlay')closeAuth()});$$('[data-quote]').forEach(b=>b.addEventListener('click',()=>showWhatsApp()));$('#show-register').addEventListener('click',()=>showAuth('register'));$('#show-recovery').addEventListener('click',()=>showAuth('recovery'));$$('[data-auth-back]').forEach(b=>b.addEventListener('click',()=>showAuth('login')));$('#login-form').addEventListener('submit',login);$('#register-form').addEventListener('submit',register);$('#recovery-form').addEventListener('submit',recovery);$('#reset-form').addEventListener('submit',resetPassword);const hashToken=new URLSearchParams(location.hash.slice(1)).get('reset_token');const queryToken=new URLSearchParams(location.search).get('reset_token');const token=hashToken||queryToken;if(token){sessionStorage.setItem('reset_token',token);history.replaceState({},'',location.pathname);openAuth('reset')}}
async function login(e){e.preventDefault();$('#login-error').textContent='';try{const body=new URLSearchParams({username:$('#login-email').value.trim().toLowerCase(),password:$('#login-password').value});await api('/auth/login',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});state.user=await api('/me');if(!state.user.is_admin)throw new Error('Sua conta ainda não possui permissão administrativa.');closeAuth();enterAdmin()}catch(err){$('#login-error').textContent=err.message;if(err.message.includes('permissão'))await api('/auth/logout',{method:'POST'}).catch(()=>{})}}
async function register(e){e.preventDefault();const msg=$('#register-message');msg.className='form-message';msg.textContent='';try{await api('/auth/register',{method:'POST',body:{name:$('#register-name').value.trim(),email:$('#register-email').value.trim().toLowerCase(),password:$('#register-password').value}});msg.classList.add('success');msg.textContent='Cadastro realizado! Agora faça login.';e.target.reset();setTimeout(()=>showAuth('login'),700)}catch(err){msg.classList.add('error');msg.textContent=err.message}}
async function recovery(e){e.preventDefault();const msg=$('#recovery-message');msg.className='form-message';try{const data=await api('/auth/password-reset/request',{method:'POST',body:{email:$('#recovery-email').value.trim().toLowerCase()}});msg.classList.add('success');msg.textContent=data.message+(data.debug_token?' Token de teste gerado.':'');if(data.debug_token){sessionStorage.setItem('reset_token',data.debug_token);setTimeout(()=>showAuth('reset'),500)}}catch(err){msg.classList.add('error');msg.textContent=err.message}}
async function resetPassword(e){e.preventDefault();const msg=$('#reset-message');msg.className='form-message';try{const token=sessionStorage.getItem('reset_token');if(!token)throw new Error('Token de recuperação não encontrado. Solicite novamente.');await api('/auth/password-reset/confirm',{method:'POST',body:{token,new_password:$('#reset-password').value}});sessionStorage.removeItem('reset_token');msg.classList.add('success');msg.textContent='Senha redefinida com sucesso. Faça login.';e.target.reset();setTimeout(()=>showAuth('login'),900)}catch(err){msg.classList.add('error');msg.textContent=err.message}}
function enterAdmin(){$('#public-site').classList.add('hidden');$('#admin-app').classList.remove('hidden');$('#user-badge').textContent=state.user?.name||'Administrador';loadDashboard()}
async function logout(){try{await api('/auth/logout',{method:'POST'})}finally{location.reload()}}
function setupAdmin(){$$('#admin-nav .nav').forEach(b=>b.addEventListener('click',()=>showSection(b.dataset.section)));$('#logout').addEventListener('click',logout);$('#modal-close').addEventListener('click',closeModal);$('#modal').addEventListener('click',e=>{if(e.target.id==='modal')closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});$('#item-form').addEventListener('submit',submitItem);$('#theme-toggle').addEventListener('click',()=>{document.body.classList.toggle('dark');localStorage.setItem('ideal-theme',document.body.classList.contains('dark')?'dark':'light')});if(localStorage.getItem('ideal-theme')==='dark')document.body.classList.add('dark')}
function showSection(name){$$('.admin-section').forEach(s=>s.classList.add('hidden'));$(`#${name}`).classList.remove('hidden');$$('#admin-nav .nav').forEach(b=>b.classList.toggle('active',b.dataset.section===name));$('#admin-title').textContent=labels[name]||'Dashboard';if(name==='dashboard')loadDashboard();else loadResource(name)}
async function loadDashboard(){const section=$('#dashboard');section.innerHTML='<div class="panel loading">Carregando visão geral...</div>';try{const [data,me]=await Promise.all([api('/admin/dashboard'),api('/me')]);state.user=me;$('#user-badge').textContent=me.name;const c=data.counts||{};const cards=[['Clientes',c.customers||0,'customers'],['Orçamentos',c.quotes||0,'quotes'],['Projetos',c.projects||0,'projects'],['Produtos',c.products||0,'products'],['Usuários',c.users||0,'users']];const recent=(data.recent_activities||[]).map(a=>`<li><strong>${escapeHtml(a.action)}</strong> · ${escapeHtml(a.description)}<small>${new Date(a.created_at).toLocaleString('pt-BR')}</small></li>`).join('')||'<li>Nenhuma atividade registrada ainda.</li>';section.innerHTML=`<div class="welcome"><div><span class="eyebrow">Visão geral</span><h2>Olá, ${escapeHtml(me.name.split(' ')[0])}. 👋</h2><p>Seu painel está conectado à API e ao PostgreSQL.</p></div><button class="btn light" onclick="createItem('quotes')">Novo orçamento</button></div><div class="stats">${cards.map(([n,v,s])=>`<button class="stat" onclick="showSection('${s}')"><span>${n}</span><strong>${v}</strong><small>Gerenciar ${n.toLowerCase()} →</small></button>`).join('')}</div><div class="panel"><div class="panel-title"><div><span class="eyebrow">Atividade</span><h3>Últimas ações</h3></div><button class="btn secondary" onclick="showSection('activities')">Ver histórico</button></div><ul class="activity-list">${recent}</ul></div>`}catch(err){section.innerHTML=`<div class="panel empty"><h2>Não foi possível carregar o painel</h2><p>${escapeHtml(err.message)}</p><button class="btn primary" onclick="loadDashboard()">Tentar novamente</button></div>`}}
const configs={customers:{title:'Clientes',endpoint:'/customers',columns:[['name','Cliente'],['email','E-mail'],['phone','Telefone'],['address','Endereço']],empty:'Nenhum cliente cadastrado.'},quotes:{title:'Orçamentos',endpoint:'/quotes',columns:[['customer_id','Cliente'],['description','Descrição'],['total','Valor'],['status','Status']],empty:'Nenhum orçamento cadastrado.'},projects:{title:'Produção e projetos',endpoint:'/projects',columns:[['name','Projeto'],['customer_id','Cliente'],['status','Etapa'],['project_date','Data']],empty:'Nenhum projeto em produção.'},suppliers:{title:'Fornecedores',endpoint:'/suppliers',columns:[['name','Fornecedor'],['contact_name','Contato'],['phone','Telefone'],['email','E-mail'],['is_active','Status']],empty:'Nenhum fornecedor cadastrado.'},materials:{title:'Insumos e custos',endpoint:'/materials',columns:[['name','Insumo'],['kind','Tipo'],['supplier_id','Fornecedor'],['unit','Unidade'],['unit_cost','Custo'],['waste_percent','Perda'],['is_active','Status']],empty:'Nenhum insumo cadastrado.'},products:{title:'Produtos',endpoint:'/products',columns:[['name','Nome'],['category_id','Categoria'],['price','Valor'],['is_active','Status']],empty:'Nenhum produto cadastrado.'},categories:{title:'Serviços',endpoint:'/categories',columns:[['name','Nome'],['description','Descrição']],empty:'Nenhum serviço cadastrado.'},users:{title:'Usuários',endpoint:'/admin/users',columns:[['name','Nome'],['email','E-mail'],['is_admin','Permissão'],['is_active','Status']],empty:'Nenhum usuário cadastrado.'},activities:{title:'Histórico de atividades',endpoint:'/activities',columns:[['action','Ação'],['entity','Entidade'],['description','Descrição'],['created_at','Data']],empty:'Nenhuma atividade registrada.'}};
async function loadResource(resource){const cfg=configs[resource],section=$(`#${resource}`);state.search='';state.status='';section.innerHTML='<div class="panel loading">Carregando...</div>';try{if(['products','projects'].includes(resource))state.categories=await api('/categories?limit=100');if(['quotes','projects'].includes(resource))state.customers=await api('/customers?limit=100');if(resource==='materials')state.suppliers=await api('/suppliers?limit=100');state.rows=await api(`${cfg.endpoint}?limit=100`);renderResource(resource)}catch(err){section.innerHTML=`<div class="panel empty"><h2>Não foi possível carregar</h2><p>${escapeHtml(err.message)}</p><button class="btn primary" onclick="loadResource('${resource}')">Tentar novamente</button></div>`}}
function rowActions(resource,row){if(resource==='activities')return'<span class="muted">Somente leitura</span>';if(resource==='users')return`<button class="small-btn" onclick="editItem('users',${row.id})">Editar</button>`;if(resource==='quotes'&&!['pending','analysis'].includes(row.status))return'<span class="muted">Proposta bloqueada</span>';return`<button class="small-btn" onclick="editItem('${resource}',${row.id})">Editar</button>${resource==='customers'?`<button class="small-btn" onclick="viewCustomerHistory(${row.id})">Histórico</button>`:''}<button class="small-btn danger" onclick="deleteItem('${resource}',${row.id})">Excluir</button>`}
function renderResource(resource){const cfg=configs[resource],section=$(`#${resource}`);let rows=state.rows.filter(row=>!state.search||Object.values(row).some(v=>String(v??'').toLowerCase().includes(state.search.toLowerCase())));if(state.status)rows=rows.filter(r=>r.status===state.status);const head=cfg.columns.map(c=>`<th>${c[1]}</th>`).join('');const body=rows.length?rows.map(row=>`<tr>${cfg.columns.map(([k])=>`<td>${formatCell(resource,k,row[k])}</td>`).join('')}<td class="actions">${rowActions(resource,row)}</td></tr>`).join(''):`<tr><td colspan="${cfg.columns.length+1}" class="empty-row">${cfg.empty}</td></tr>`;const createButton=['users','activities'].includes(resource)?'':`<button class="btn primary" onclick="createItem('${resource}')">+ Novo</button>`;const statusFilter=['quotes','projects'].includes(resource)?`<select class="filter" onchange="setStatus('${resource}',this.value)"><option value="">Todos os status</option>${Object.entries(statusLabels).filter(([k])=>resource==='quotes'?['pending','analysis','approved','rejected','completed'].includes(k):['planning','in_progress','completed','cancelled'].includes(k)).map(([k,v])=>`<option value="${k}" ${state.status===k?'selected':''}>${v}</option>`).join('')}</select>`:'';section.innerHTML=`<div class="panel"><div class="toolbar"><div><span class="eyebrow">Gerenciamento</span><h2>${cfg.title}</h2><p>${rows.length} registro(s)</p></div><div class="toolbar-actions"><input id="search-${resource}" placeholder="Pesquisar..." value="${escapeHtml(state.search)}" oninput="setSearch('${resource}',this.value)">${statusFilter}${createButton}</div></div><div class="table-wrap"><table class="table"><thead><tr>${head}<th>Ações</th></tr></thead><tbody>${body}</tbody></table></div></div>`}
function setSearch(resource,value){state.search=value;renderResource(resource);const input=$(`#search-${resource}`);if(input){input.focus();input.setSelectionRange(value.length,value.length)}}
function setStatus(resource,value){state.status=value;renderResource(resource)}
function formatCell(resource,key,value){if(value===null||value===undefined||value==='')return'<span class="muted">—</span>';if(['price','total','unit_cost'].includes(key))return money(value);if(key==='waste_percent')return`${escapeHtml(value)}%`;if(key==='is_admin')return value?'<span class="badge success">Administrador</span>':'<span class="badge">Usuário</span>';if(key==='is_active')return value?'<span class="badge success">Ativo</span>':'<span class="badge">Inativo</span>';if(key==='status')return`<span class="badge">${escapeHtml(statusLabels[value]||value)}</span>`;if(key==='kind')return escapeHtml({mdf:'MDF',hardware:'Ferragem',profile:'Perfil',accessory:'Acessório',finish:'Acabamento',service:'Serviço',other:'Outro'}[value]||value);if(key==='category_id')return escapeHtml(state.categories.find(x=>x.id===value)?.name||`#${value}`);if(key==='customer_id')return escapeHtml(state.customers.find(x=>x.id===value)?.name||`#${value}`);if(key==='supplier_id')return escapeHtml(state.suppliers.find(x=>x.id===value)?.name||`#${value}`);if(key==='created_at'||key==='project_date')return new Date(value).toLocaleString('pt-BR');return escapeHtml(value)}
function field(label,name,type='text',value='',required=false,extra=''){return`<label for="${name}">${label}${type==='textarea'?`<textarea id="${name}" name="${name}" ${required?'required':''} ${extra}>${escapeHtml(value)}</textarea>`:`<input id="${name}" name="${name}" type="${type}" value="${escapeHtml(value)}" ${required?'required':''} ${extra}>`}</label>`}
function supplierFormHtml(row={}){return field('Nome','name','text',row.name||'',true,'maxlength="160"')+field('Pessoa de contato','contact_name','text',row.contact_name||'',false,'maxlength="160"')+field('Telefone','phone','tel',row.phone||'',false,'maxlength="40"')+field('E-mail','email','email',row.email||'')+field('Observações','notes','textarea',row.notes||'',false,'maxlength="5000"')+`<label class="check"><input name="is_active" type="checkbox" ${row.is_active!==false?'checked':''}> Ativo</label>`}
function materialFormHtml(row={}){const kinds={mdf:'MDF',hardware:'Ferragem',profile:'Perfil',accessory:'Acessório',finish:'Acabamento',service:'Serviço',other:'Outro'};return `<label>Fornecedor<select name="supplier_id"><option value="">Sem fornecedor</option>${state.suppliers.map(o=>`<option value="${o.id}" ${String(o.id)===String(row.supplier_id)?'selected':''}>${escapeHtml(o.name)}</option>`).join('')}</select></label>`+field('Nome','name','text',row.name||'',true,'maxlength="180"')+`<label>Tipo<select name="kind" required><option value="">Selecione...</option>${Object.entries(kinds).map(([k,v])=>`<option value="${k}" ${row.kind===k?'selected':''}>${v}</option>`).join('')}</select></label>`+field('Unidade','unit','text',row.unit||'un',true,'maxlength="30"')+field('Custo unitário','unit_cost','number',row.unit_cost??0,true,'min="0" step="0.01"')+field('Perda prevista (%)','waste_percent','number',row.waste_percent??0,true,'min="0" max="100" step="0.01"')+`<label class="check"><input name="is_active" type="checkbox" ${row.is_active!==false?'checked':''}> Ativo</label>`}
function selectField(label,name,options,value=''){return`<label>${label}<select name="${name}" required><option value="">Selecione...</option>${options.map(o=>`<option value="${o.id}" ${String(o.id)===String(value)?'selected':''}>${escapeHtml(o.name)}</option>`).join('')}</select></label>`}
function formHtml(resource,row={}){if(resource==='customers')return field('Nome','name','text',row.name||'',true,'maxlength="160"')+field('E-mail','email','email',row.email||'')+field('Telefone','phone','tel',row.phone||'')+field('Endereço','address','text',row.address||'',false,'maxlength="500"');if(resource==='categories')return field('Nome','name','text',row.name||'',true,'maxlength="120"')+field('Descrição','description','textarea',row.description||'',false,'maxlength="500"');if(resource==='products')return selectField('Categoria','category_id',state.categories,row.category_id)+field('Nome','name','text',row.name||'',true,'maxlength="160"')+field('Descrição','description','textarea',row.description||'')+field('Valor','price','number',row.price??0,true,'min="0" step="0.01"')+field('Imagem (URL)','image_url','url',row.image_url||'')+`<label class="check"><input name="is_active" type="checkbox" ${row.is_active!==false?'checked':''}> Ativo</label>`;if(resource==='quotes')return selectField('Cliente','customer_id',state.customers,row.customer_id)+field('Descrição','description','textarea',row.description||'',true,'maxlength="3000"')+field('Medidas','measurements','textarea',row.measurements||'',false,'maxlength="2000" placeholder="Ex.: 2,40m x 0,60m"')+field('Materiais','materials','textarea',row.materials||'',false,'maxlength="2000"')+field('Material','material_cost','number',row.material_cost??0,true,'min="0" step="0.01"')+field('Ferragens','hardware_cost','number',row.hardware_cost??0,true,'min="0" step="0.01"')+field('Mão de obra','labor_cost','number',row.labor_cost??0,true,'min="0" step="0.01"')+field('Acabamento','finishing_cost','number',row.finishing_cost??0,true,'min="0" step="0.01"')+field('Margem de lucro (%)','profit_margin','number',row.profit_margin??30,true,'min="0" max="100" step="0.01"');if(resource==='projects')return selectField('Cliente','customer_id',state.customers,row.customer_id)+field('Nome do projeto','name','text',row.name||'',true,'maxlength="160"')+field('Descrição','description','textarea',row.description||'',false,'maxlength="5000"')+field('Medidas','measurements','textarea',row.measurements||'',false,'maxlength="2000"')+field('Materiais','materials','textarea',row.materials||'',false,'maxlength="2000"')+field('Data','project_date','date',row.project_date||'')+`<label>Status<select name="status"><option value="planning" ${row.status==='planning'||!row.status?'selected':''}>Planejamento</option><option value="in_progress" ${row.status==='in_progress'?'selected':''}>Em andamento</option><option value="completed" ${row.status==='completed'?'selected':''}>Concluído</option><option value="cancelled" ${row.status==='cancelled'?'selected':''}>Cancelado</option></select></label>`+field('Fotos (URLs, uma por linha)','photos','textarea',(row.photos||[]).join('\n'),false,'placeholder="https://..."');if(resource==='users')return field('Nome','name','text',row.name||'',true,'maxlength="120"')+field('E-mail','email','email',row.email||'',true)+`<label>Status<select name="is_active"><option value="true" ${row.is_active?'selected':''}>Ativo</option><option value="false" ${!row.is_active?'selected':''}>Inativo</option></select></label><label>Permissão<select name="is_admin"><option value="true" ${row.is_admin?'selected':''}>Administrador</option><option value="false" ${!row.is_admin?'selected':''}>Usuário</option></select></label>`}
async function openForm(resource,id=null){state.resource=resource;state.id=id;let row={};if(['products','projects'].includes(resource)&&!state.categories.length)state.categories=await api('/categories?limit=100');if(['quotes','projects'].includes(resource)&&!state.customers.length)state.customers=await api('/customers?limit=100');if(resource==='materials'&&!state.suppliers.length)state.suppliers=await api('/suppliers?limit=100');if(id)row=state.rows.find(x=>x.id===id)||await api(`${configs[resource].endpoint}/${id}`);$('#modal-title').textContent=`${id?'Editar':'Novo'} ${resource==='quotes'?'orçamento':resource==='customers'?'cliente':resource==='projects'?'projeto':resource==='suppliers'?'fornecedor':resource==='materials'?'insumo':resource==='products'?'produto':resource==='categories'?'serviço':'usuário'}`;$('#item-form').innerHTML=`<div class="form-grid">${formHtml(resource,row)}</div><div class="modal-actions"><button type="button" class="btn secondary" onclick="closeModal()">Cancelar</button><button type="submit" class="btn primary">${id?'Salvar alterações':'Cadastrar'}</button></div>`;$('#modal').classList.remove('hidden');$('#modal').setAttribute('aria-hidden','false')}
function createItem(resource){openForm(resource)}function editItem(resource,id){openForm(resource,id)}function closeModal(){$('#modal').classList.add('hidden');$('#modal').setAttribute('aria-hidden','true');$('#item-form').innerHTML=''}
async function submitItem(e){e.preventDefault();const fd=new FormData(e.target),resource=state.resource,p={};for(const [k,v] of fd.entries())p[k]=v;if(resource==='products'){p.category_id=Number(p.category_id);p.price=Number(p.price);p.is_active=fd.has('is_active')}if(resource==='quotes'){p.customer_id=Number(p.customer_id);['material_cost','hardware_cost','labor_cost','finishing_cost','profit_margin'].forEach(key=>{p[key]=Number(p[key]||0)})}if(resource==='projects'){p.customer_id=Number(p.customer_id);p.photos=String(p.photos||'').split(/\n|,/).map(x=>x.trim()).filter(Boolean)}if(resource==='suppliers')p.is_active=fd.has('is_active');if(resource==='materials'){p.supplier_id=p.supplier_id?Number(p.supplier_id):null;p.unit_cost=Number(p.unit_cost||0);p.waste_percent=Number(p.waste_percent||0);p.is_active=fd.has('is_active')}if(resource==='users'){p.is_active=p.is_active==='true';p.is_admin=p.is_admin==='true'}try{const endpoint=resource==='users'?`/admin/users/${state.id}`:state.id?`${configs[resource].endpoint}/${state.id}`:configs[resource].endpoint;const method=resource==='users'?'PATCH':state.id?'PUT':'POST';await api(endpoint,{method,body:p});closeModal();toast(state.id?'Alterações salvas com sucesso.':'Cadastro realizado com sucesso.');await loadResource(resource)}catch(err){toast(err.message,'error')}}
async function deleteItem(resource,id){if(!confirm('Excluir este registro? Esta ação não pode ser desfeita.'))return;try{await api(`${configs[resource].endpoint}/${id}`,{method:'DELETE'});toast('Registro excluído.');await loadResource(resource)}catch(err){toast(err.message,'error')}}
async function viewCustomerHistory(id){try{const customer=state.rows.find(x=>x.id===id);const history=await api(`/customers/${id}/history?limit=100`);$('#modal-title').textContent=`Histórico — ${customer?.name||`Cliente #${id}`}`;$('#item-form').innerHTML=`<div class="history-modal">${history.length?history.map(a=>`<div class="history-item"><strong>${escapeHtml(a.description)}</strong><span>${new Date(a.created_at).toLocaleString('pt-BR')}</span></div>`).join(''):'<p class="muted">Nenhuma atividade para este cliente.</p>'}</div><div class="modal-actions"><button type="button" class="btn secondary" onclick="closeModal()">Fechar</button></div>`;$('#modal').classList.remove('hidden')}catch(err){toast(err.message,'error')}}
function projectFormHtmlBefore(row={}){return selectField('Cliente','customer_id',state.customers,row.customer_id)+field('Nome do projeto','name','text',row.name||'',true,'maxlength="160"')+field('Descrição','description','textarea',row.description||'',false,'maxlength="5000"')+field('Medidas','measurements','textarea',row.measurements||'',false,'maxlength="2000"')+field('Materiais','materials','textarea',row.materials||'',false,'maxlength="2000"')+field('Data','project_date','date',row.project_date||'')+field('Fotos (URLs, uma por linha)','photos','textarea',(row.photos||[]).join('\n'),false,'placeholder="https://..."')}
function supplierFormHtmlForResourceBefore(row={}){return field('Nome','name','text',row.name||'',true,'maxlength="160"')+field('Pessoa de contato','contact_name','text',row.contact_name||'',false,'maxlength="160"')+field('Telefone','phone','tel',row.phone||'',false,'maxlength="40"')+field('E-mail','email','email',row.email||'')+field('Observações','notes','textarea',row.notes||'',false,'maxlength="5000"')+`<label class="check"><input name="is_active" type="checkbox" ${row.is_active!==false?'checked':''}> Ativo</label>`}
function materialFormHtmlForResourceBefore(row={}){const kinds={mdf:'MDF',hardware:'Ferragem',profile:'Perfil',accessory:'Acessório',finish:'Acabamento',service:'Serviço',other:'Outro'};return `<label for="supplier_id">Fornecedor<select id="supplier_id" name="supplier_id"><option value="">Sem fornecedor</option>${(state.suppliers||[]).map(o=>`<option value="${o.id}" ${String(o.id)===String(row.supplier_id)?'selected':''}>${escapeHtml(o.name)}</option>`).join('')}</select></label>`+field('Nome','name','text',row.name||'',true,'maxlength="180"')+`<label for="kind">Tipo<select id="kind" name="kind" required><option value="">Selecione...</option>${Object.entries(kinds).map(([k,v])=>`<option value="${k}" ${row.kind===k?'selected':''}>${v}</option>`).join('')}</select></label>`+field('Unidade','unit','text',row.unit||'un',true,'maxlength="30"')+field('Custo unitário','unit_cost','number',row.unit_cost??0,true,'min="0" step="0.01"')+field('Perda prevista (%)','waste_percent','number',row.waste_percent??0,true,'min="0" max="100" step="0.01"')+`<label class="check"><input name="is_active" type="checkbox" ${row.is_active!==false?'checked':''}> Ativo</label>`}
const legacyFormHtmlBeforeBoot = formHtml;
formHtml = function(resource,row={}){if(resource==='suppliers')return supplierFormHtmlForResourceBefore(row);if(resource==='materials')return materialFormHtmlForResourceBefore(row);if(resource==='projects')return projectFormHtmlBefore(row);return legacyFormHtmlBeforeBoot(resource,row)};
async function boot(){setupPublic();setupAdmin();try{await api('/auth/csrf');const me=await api('/me');if(me?.is_admin){state.user=me;enterAdmin()}}catch(_){} }
function projectFormHtml(row={}){return selectField('Cliente','customer_id',state.customers,row.customer_id)+field('Nome do projeto','name','text',row.name||'',true,'maxlength="160"')+field('Descrição','description','textarea',row.description||'',false,'maxlength="5000"')+field('Medidas','measurements','textarea',row.measurements||'',false,'maxlength="2000"')+field('Materiais','materials','textarea',row.materials||'',false,'maxlength="2000"')+field('Data','project_date','date',row.project_date||'')+field('Fotos (URLs, uma por linha)','photos','textarea',(row.photos||[]).join('\n'),false,'placeholder="https://..."')}
function supplierFormHtmlForResource(row={}){return field('Nome','name','text',row.name||'',true,'maxlength="160"')+field('Pessoa de contato','contact_name','text',row.contact_name||'',false,'maxlength="160"')+field('Telefone','phone','tel',row.phone||'',false,'maxlength="40"')+field('E-mail','email','email',row.email||'')+field('Observações','notes','textarea',row.notes||'',false,'maxlength="5000"')+`<label class="check"><input name="is_active" type="checkbox" ${row.is_active!==false?'checked':''}> Ativo</label>`}
function materialFormHtmlForResource(row={}){const kinds={mdf:'MDF',hardware:'Ferragem',profile:'Perfil',accessory:'Acessório',finish:'Acabamento',service:'Serviço',other:'Outro'};return `<label for="supplier_id">Fornecedor<select id="supplier_id" name="supplier_id"><option value="">Sem fornecedor</option>${(state.suppliers||[]).map(o=>`<option value="${o.id}" ${String(o.id)===String(row.supplier_id)?'selected':''}>${escapeHtml(o.name)}</option>`).join('')}</select></label>`+field('Nome','name','text',row.name||'',true,'maxlength="180"')+`<label for="kind">Tipo<select id="kind" name="kind" required><option value="">Selecione...</option>${Object.entries(kinds).map(([k,v])=>`<option value="${k}" ${row.kind===k?'selected':''}>${v}</option>`).join('')}</select></label>`+field('Unidade','unit','text',row.unit||'un',true,'maxlength="30"')+field('Custo unitário','unit_cost','number',row.unit_cost??0,true,'min="0" step="0.01"')+field('Perda prevista (%)','waste_percent','number',row.waste_percent??0,true,'min="0" max="100" step="0.01"')+`<label class="check"><input name="is_active" type="checkbox" ${row.is_active!==false?'checked':''}> Ativo</label>`}
const projectNextStatus={planning:'measurement',in_progress:'production',measurement:'technical_design',technical_design:'purchasing',purchasing:'production',production:'installation',installation:'delivered',delivered:'completed'};
async function advanceProject(id,status){try{await api(`/projects/${id}/status`,{method:'PATCH',body:{status}});toast(`Projeto avançou para ${statusLabels[status]||status}.`);await loadResource('projects')}catch(err){toast(err.message,'error')}}
async function submitProjectCost(projectId){const description=$('#cost-description')?.value.trim(),materialId=$('#cost-material')?.value,category=$('#cost-category')?.value,quantity=Number($('#cost-quantity')?.value||1),unitCost=Number($('#cost-unit-cost')?.value||0);if(!description||!category||quantity<=0||unitCost<0){toast('Preencha descrição, categoria, quantidade e custo.','error');return}try{await api('/project-costs',{method:'POST',body:{project_id:projectId,material_id:materialId?Number(materialId):null,category,description,quantity,unit_cost:unitCost}});toast('Custo adicionado.');await openProjectCosts(projectId)}catch(err){toast(err.message,'error')}}
async function openProjectCosts(projectId){try{const [projectCosts,materials,project]=await Promise.all([api(`/project-costs/project/${projectId}`),api('/materials?limit=100'),api(`/projects/${projectId}`)]);const total=projectCosts.reduce((sum,item)=>sum+Number(item.total_cost||0),0);$('#modal-title').textContent=`Custos — ${project.name||`Projeto #${projectId}`}`;const rows=projectCosts.length?projectCosts.map(item=>`<tr><td>${escapeHtml(item.description)}</td><td>${escapeHtml(statusLabels[item.category]||item.category)}</td><td>${item.quantity}</td><td>${money(item.total_cost)}</td></tr>`).join(''):'<tr><td colspan="4" class="empty-row">Nenhum custo lançado.</td></tr>';$('#item-form').innerHTML=`<div class="cost-panel"><div class="cost-summary"><span>Total previsto</span><strong>${money(total)}</strong></div><div class="table-wrap"><table class="table"><thead><tr><th>Descrição</th><th>Categoria</th><th>Qtd.</th><th>Total</th></tr></thead><tbody>${rows}</tbody></table></div><div class="cost-entry"><h3>Adicionar custo</h3><div class="form-grid"><label>Insumo<select id="cost-material"><option value="">Sem vínculo</option>${materials.map(m=>`<option value="${m.id}" data-unit-cost="${m.unit_cost}">${escapeHtml(m.name)} · ${money(m.unit_cost)}/${escapeHtml(m.unit)}</option>`).join('')}</select></label><label>Categoria<select id="cost-category"><option value="material">Material</option><option value="labor">Mão de obra</option><option value="freight">Frete</option><option value="installation">Instalação</option><option value="outsourcing">Terceirização</option><option value="tax">Imposto</option><option value="other">Outro</option></select></label>${field('Descrição','cost-description','text','',true,'maxlength="500" placeholder="Ex.: MDF branco 18 mm"')}${field('Quantidade','cost-quantity','number',1,true,'min="0.001" step="0.001"')}${field('Custo unitário','cost-unit-cost','number',0,true,'min="0" step="0.01"')}</div><button type="button" class="btn primary" onclick="submitProjectCost(${projectId})">Adicionar custo</button></div></div><div class="modal-actions"><button type="button" class="btn secondary" onclick="closeModal()">Fechar</button></div>`;$('#cost-material').addEventListener('change',e=>{const cost=e.target.selectedOptions[0]?.dataset.unitCost;if(cost!==undefined)$('#cost-unit-cost').value=cost});$('#modal').classList.remove('hidden');$('#modal').setAttribute('aria-hidden','false')}catch(err){toast(err.message,'error')}}
const legacyRowActions=rowActions;
rowActions=function(resource,row){let html=legacyRowActions(resource,row);if(resource==='projects'&&!['completed','cancelled'].includes(row.status)){const next=projectNextStatus[row.status];html+=`<button class="small-btn" onclick="openProjectCosts(${row.id})">Custos</button>${next?`<button class="small-btn primary-action" onclick="advanceProject(${row.id},'${next}')">Avançar →</button>`:''}`}return html};
const legacyFormHtml = formHtml;
formHtml = function(resource,row={}){if(resource==='suppliers')return supplierFormHtmlForResource(row);if(resource==='materials')return materialFormHtmlForResource(row);if(resource==='projects')return projectFormHtml(row);return legacyFormHtml(resource,row)};
function ensureOperationsNav(){const nav=$('#admin-nav'),main=$('.admin-main');if(!nav||!main)return;const products=nav.querySelector('[data-section="products"]');if(!nav.querySelector('[data-section="suppliers"]'))products?.insertAdjacentHTML('beforebegin','<button class="nav" data-section="suppliers" type="button">⌁ <span>Fornecedores</span></button><button class="nav" data-section="materials" type="button">▨ <span>Insumos</span></button>');if(!$('#suppliers'))products?.parentElement&&main.insertAdjacentHTML('beforeend','<section id="suppliers" class="admin-section hidden"></section><section id="materials" class="admin-section hidden"></section>')}
const legacySetupAdmin = setupAdmin;
setupAdmin = function(){ensureOperationsNav();return legacySetupAdmin()};
const legacyLoadDashboard = loadDashboard;
loadDashboard = async function(){const section=$('#dashboard');section.innerHTML='<div class="panel loading">Carregando visão geral...</div>';try{const [data,me]=await Promise.all([api('/admin/dashboard'),api('/me')]);state.user=me;$('#user-badge').textContent=me.name;const c=data.counts||{},firstName=escapeHtml((me.name||'Administrador').split(' ')[0]),recent=(data.recent_activities||[]).slice(0,5).map(a=>`<li><strong>${escapeHtml(a.description)}</strong><span>${new Date(a.created_at).toLocaleDateString('pt-BR')}</span></li>`).join('')||'<li><span>Nenhuma atividade registrada ainda.</span></li>';const kpis=[['Clientes',c.customers||0,'Base ativa'],['Orçamentos',c.quotes||0,'Este período'],['Projetos',c.projects||0,'Em andamento'],['Produtos',c.products||0,'No catálogo'],['Equipe',c.users||0,'Usuários ativos']];section.innerHTML=`<div class="dashboard-header"><div><span class="eyebrow">Bem-vindo ao futuro da marcenaria</span><h2>Gestão completa.<br><span class="accent-text">Resultados extraordinários.</span></h2></div><div class="dashboard-search"><input type="search" aria-label="Buscar no painel" placeholder="Buscar clientes, projetos, orçamentos..."></div></div><div class="dashboard-hero"><div class="dashboard-hero-copy"><span class="eyebrow">Olá, ${firstName}</span><h3>Mais clareza para vender, produzir e lucrar.</h3><p>Centralize a operação da sua marcenaria em uma visão simples, elegante e inteligente.</p><div class="dashboard-hero-actions"><button class="btn primary" onclick="createItem('quotes')">Solicitar orçamento</button><button class="btn secondary" onclick="showSection('projects')">Ver produção</button></div></div><div class="dashboard-hero-visual" role="img" aria-label="Visual premium da operação de uma marcenaria"><div class="hero-visual-card"><span class="eyebrow">Orçamentos com IA</span><strong>Da ideia à proposta, em poucos segundos.</strong><small>Materiais, margem e produção em um só lugar.</small></div></div></div><div class="dashboard-kpis">${kpis.map(([name,value,caption])=>`<button class="dashboard-kpi" onclick="showSection('${name==='Clientes'?'customers':name==='Orçamentos'?'quotes':name==='Projetos'?'projects':name==='Produtos'?'products':'users'}')"><span>${name}</span><strong>${value}</strong><small>${caption} →</small></button>`).join('')}</div><div class="dashboard-overview"><div class="panel"><div class="panel-title"><div><span class="eyebrow">Resumo operacional</span><h3>Atividade recente</h3></div><button class="btn secondary" onclick="showSection('activities')">Ver todos</button></div><ul class="dashboard-list">${recent}</ul></div><div class="panel"><div class="panel-title"><div><span class="eyebrow">Próximo passo</span><h3>Organize sua operação</h3></div></div><p class="muted">Cadastre fornecedores e insumos para deixar o cálculo de custos ainda mais preciso.</p><div class="dashboard-hero-actions"><button class="btn secondary" onclick="showSection('suppliers')">Fornecedores</button><button class="btn secondary" onclick="showSection('materials')">Insumos</button></div></div></div>`}catch(err){section.innerHTML=`<div class="panel empty"><h2>Não foi possível carregar o painel</h2><p>${escapeHtml(err.message)}</p><button class="btn primary" onclick="loadDashboard()">Tentar novamente</button></div>`}};
function ensureReferenceChrome(){
  const sidebar=$('.sidebar'),brand=sidebar?.querySelector('.side-brand'),mark=brand?.querySelector('.logo-mark');
  if(mark&&!mark.dataset.referenceLogo){mark.innerHTML='<span class="reference-monogram" aria-hidden="true">M</span>';mark.dataset.referenceLogo='true'}
  const sideCopy=brand?.querySelector('div');if(sideCopy){const small=sideCopy.querySelector('small');if(small)small.textContent='Gestão inteligente para marcenarias do futuro.'}
  const nav=$('#admin-nav');nav?.querySelectorAll('.nav').forEach(button=>{if(button.querySelector('.nav-icon'))return;const iconText=[...button.childNodes].find(node=>node.nodeType===Node.TEXT_NODE&&node.textContent.trim())?.textContent.trim()||'•';const icon=document.createElement('span');icon.className='nav-icon';icon.setAttribute('aria-hidden','true');icon.textContent=iconText;const label=button.querySelector('span');if(label)label.classList.add('nav-label');[...button.childNodes].filter(node=>node.nodeType===Node.TEXT_NODE).forEach(node=>node.remove());button.prepend(icon)});
  const bottom=sidebar?.querySelector('.side-bottom');if(bottom&&!bottom.querySelector('.side-plan-card'))bottom.insertAdjacentHTML('afterbegin','<div class="side-plan-card"><span class="plan-crown" aria-hidden="true">♕</span><strong>Plano Profissional</strong><small>Sua marcenaria em outro nível.</small><a href="#planos">Ver plano <span aria-hidden="true">→</span></a></div>');
  const topbar=$('.topbar');if(topbar&&!topbar.dataset.referenceReady){const titleWrap=topbar.firstElementChild;titleWrap.classList.add('reference-topbar-search');titleWrap.innerHTML='<label class="reference-search" for="dashboard-global-search"><span aria-hidden="true">⌕</span><input id="dashboard-global-search" type="search" placeholder="Buscar clientes, projetos, orçamentos..." autocomplete="off"><kbd>⌘ K</kbd></label><h1 id="admin-title" class="sr-only">Dashboard</h1>';const actions=topbar.querySelector('.top-actions');if(actions&&!actions.querySelector('.notification-button'))actions.insertAdjacentHTML('afterbegin','<button class="icon-button notification-button" type="button" aria-label="Notificações">♧<span aria-hidden="true"></span></button><span class="topbar-divider" aria-hidden="true"></span>');const user=actions?.querySelector('.user-pill'),badge=user?.querySelector('#user-badge');if(user&&badge&&!user.querySelector('.user-meta')){const name=badge.textContent;user.innerHTML='<span class="user-meta"><strong id="user-badge">'+escapeHtml(name)+'</strong><small>Administrador</small></span><span class="user-avatar"><span class="user-avatar-mark" aria-hidden="true">M</span></span><span class="user-chevron" aria-hidden="true">⌄</span>'}topbar.dataset.referenceReady='true'}
}
const legacyEnsureOperationsNav = ensureOperationsNav;
ensureOperationsNav = function(){legacyEnsureOperationsNav();ensureReferenceChrome();const label=$('#admin-nav [data-section="dashboard"] .nav-label');if(label)label.textContent='Início'};

const referenceLoadDashboard = loadDashboard;
loadDashboard = async function(){
  const section=$('#dashboard');section.innerHTML='<div class="panel loading">Carregando visão geral...</div>';
  try{
    const [data,me]=await Promise.all([api('/admin/dashboard'),api('/me')]);
    state.user=me;$('#user-badge').textContent=me.name||'Administrador';
    const counts=data.counts||{}, trends=data.trends||{}, finance=data.finance||{};
    const safe=(value,fallback='—')=>value===null||value===undefined||value===''?fallback:value;
    const number=(value)=>Number.isFinite(Number(value))?new Intl.NumberFormat('pt-BR').format(Number(value)):'—';
    const moneyValue=(value)=>value===null||value===undefined||value===''?'—':new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(Number(value));
    const firstName=escapeHtml((me.name||'Administrador').split(' ')[0]);
    const activities=(data.recent_activities||[]).slice(0,6);
    const dashboardCards=data.dashboard_cards||{};
    const cardItems=(key,empty)=>Array.isArray(dashboardCards[key])?dashboardCards[key]:[];
    const initials=(name='')=>escapeHtml(name.split(/\\s+/).map(part=>part[0]).join('').slice(0,2).toUpperCase()||'—');
    const date=(value)=>value?new Date(value).toLocaleDateString('pt-BR'):'—';
    const customerItems=cardItems('customers');
    const quoteItems=cardItems('quotes');
    const productItems=cardItems('products');
    const project=dashboardCards.projects?.[0]||null;
    const listEmpty='<li class="reference-empty">Nenhum registro recente.</li>';
    const customerRows=(customerItems.length?customerItems.map(item=>`<li><span class="reference-avatar">${initials(item.name)}</span><span class="reference-row-copy"><strong>${escapeHtml(item.name||'Cliente')}</strong><small>${escapeHtml(item.subtitle||item.description||'Cliente ativo')}</small></span><span class="reference-status success">${escapeHtml(item.status||'Ativo')}</span></li>`).join(''):listEmpty);
    const quoteRows=(quoteItems.length?quoteItems.map(item=>`<li><span class="reference-row-copy"><strong>${escapeHtml(item.name||`Orçamento #${item.id||'—'}`)}</strong><small>${escapeHtml(item.subtitle||item.description||'Projeto planejado')}</small></span><span class="reference-row-value"><strong>${moneyValue(item.total)}</strong><small class="reference-status ${item.status==='Enviado'?'success':'warning'}">${escapeHtml(item.status||'Em análise')}</small></span></li>`).join(''):listEmpty);
    const productRows=(productItems.length?productItems.map(item=>`<li><span class="product-thumb ${escapeHtml(item.kind||'wood')}" aria-hidden="true"></span><span class="reference-row-copy"><strong>${escapeHtml(item.name||'Insumo')}</strong><small>${escapeHtml(item.subtitle||item.category||'Materiais')}</small></span><span class="reference-status ${item.low_stock?'warning':'success'}">${escapeHtml(item.low_stock?'Estoque baixo':'Em estoque')}</span></li>`).join(''):listEmpty);
    const activityRows=(activities.length?activities.map(item=>`<li><span class="reference-row-copy"><strong>${escapeHtml(item.description||item.action||'Atividade')}</strong><small>${date(item.created_at)}</small></span></li>`).join(''):listEmpty);
    const kpis=[
      ['customers','♧','Clientes',number(counts.customers),'Clientes ativos',safe(trends.customers,'Base ativa')],
      ['quotes','▤','Orçamentos',number(counts.quotes),'Orçamentos',safe(trends.quotes,'No período')],
      ['projects','▦','Projetos',number(counts.projects),'Projetos em andamento',safe(trends.projects,'Em andamento')],
      ['activities','$','Faturamento',moneyValue(finance.revenue??data.revenue),'Faturamento do mês',safe(trends.revenue,'Configure o financeiro')],
      ['products','▧','Produtos',number(counts.products),'Produtos cadastrados',safe(trends.products,'No catálogo')]
    ];
    section.innerHTML=`<div class="dashboard-header reference-dashboard-header"><div class="reference-dashboard-spacer" aria-hidden="true"></div></div><div class="dashboard-hero reference-hero"><div class="dashboard-hero-copy reference-hero-copy"><span class="reference-kicker"><i aria-hidden="true"></i>Bem-vindo ao futuro da marcenaria</span><h2>Gestão completa.<br>Resultados <span class="accent-text">extraordinários.</span></h2><p>O Multi-Marcenarias centraliza sua operação, aumenta sua produtividade e impulsiona seus lucros com tecnologia de ponta.</p><div class="dashboard-hero-actions"><button class="btn primary" onclick="createItem('quotes')">Solicitar orçamento <span aria-hidden="true">→</span></button><button class="btn secondary" onclick="showSection('quotes')">Ver demonstração <span aria-hidden="true">▷</span></button></div><div class="reference-benefits"><span><b aria-hidden="true">✦</b><strong>Orçamentos com IA<small>Mais precisão e agilidade</small></strong></span><span><b aria-hidden="true">♢</b><strong>Gestão integrada<small>Tudo em um só lugar</small></strong></span><span><b aria-hidden="true">↗</b><strong>Mais lucro<small>Decisões inteligentes</small></strong></span></div></div><div class="dashboard-hero-visual reference-hero-visual" role="img" aria-label="Cozinha planejada com marcenaria premium"><div class="hero-visual-card"><span class="eyebrow">Orçamentos com IA</span><strong>Nossa IA analisa materiais, mão de obra e detalhes do projeto para gerar orçamentos precisos em segundos.</strong><button class="btn light" onclick="showSection('quotes')">Saiba mais <span aria-hidden="true">→</span></button></div></div></div><div class="dashboard-kpis reference-kpis">${kpis.map(([target,icon,name,value,caption,trend])=>`<button class="dashboard-kpi reference-kpi" onclick="showSection('${target}')"><span class="reference-kpi-icon" aria-hidden="true">${icon}</span><span class="reference-kpi-copy"><strong>${value}</strong><span>${caption}</span><small>${escapeHtml(String(trend))}</small></span></button>`).join('')}</div><div class="reference-card-grid"><article class="panel reference-card"><div class="reference-card-head"><h3><span aria-hidden="true">♧</span>Clientes</h3><button class="small-btn" onclick="showSection('customers')">Ver todos <span aria-hidden="true">→</span></button></div><ul class="reference-rows">${customerRows}</ul></article><article class="panel reference-card"><div class="reference-card-head"><h3><span aria-hidden="true">▤</span>Orçamentos</h3><button class="small-btn" onclick="showSection('quotes')">Ver todos <span aria-hidden="true">→</span></button></div><ul class="reference-rows">${quoteRows}</ul></article><article class="panel reference-card reference-project-card"><div class="reference-card-head"><h3><span aria-hidden="true">▦</span>Projetos</h3><button class="small-btn" onclick="showSection('projects')">Ver todos <span aria-hidden="true">→</span></button></div><div class="reference-project-image" role="img" aria-label="Projeto de cozinha planejada"></div><div class="reference-project-meta"><strong>${escapeHtml(project?.name||'Projeto em andamento')}</strong><span>${escapeHtml(project?.subtitle||'Acompanhe a produção')}</span></div><div class="reference-progress"><span><i style="width:${Math.min(100,Math.max(0,Number(project?.progress||65)))}%"></i></span><strong>${safe(project?.progress,'—')}${project?.progress!==undefined?'%':''}</strong></div><div class="reference-project-dates"><span>◷ Início: ${date(project?.start_date)}</span><span>◷ Entrega: ${date(project?.due_date)}</span></div></article><article class="panel reference-card"><div class="reference-card-head"><h3><span aria-hidden="true">▧</span>Produtos</h3><button class="small-btn" onclick="showSection('products')">Ver todos <span aria-hidden="true">→</span></button></div><ul class="reference-rows">${productRows}</ul></article></div><div class="reference-ai-band"><span class="reference-ai-icon" aria-hidden="true">✦</span><span><strong>Orçamentos com IA: mais precisão, menos tempo</strong><small>Use inteligência artificial para calcular materiais, mão de obra e sugerir preços com mais assertividade.</small></span><button class="btn primary" onclick="showSection('quotes')">Experimentar agora <span aria-hidden="true">✦</span></button></div><div class="reference-activity-fallback hidden" aria-hidden="true">${activityRows}</div>`;
  }catch(err){section.innerHTML=`<div class="panel empty"><h2>Não foi possível carregar o painel</h2><p>${escapeHtml(err.message)}</p><button class="btn primary" onclick="loadDashboard()">Tentar novamente</button></div>`}
};
boot();
